def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved polynomial bivariadic model for log10(|ID|/A)."""
    a0, a1, a2, a3, a4 = parameters
    return a0 + a1 * gate_voltage_abs + a2 * drain_voltage_abs + a3 * gate_voltage_abs * drain_voltage_abs + a4 * (gate_voltage_abs + drain_voltage_abs)
